<form class="contact-form" id="contact-form" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post"><input type="hidden" name="action" value="rzz_contact"><?php wp_nonce_field('rzz_contact','rzz_nonce'); ?><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><?php $status=sanitize_key($_GET['enquiry']??'');$messages=['sent'=>'Thank you. Your enquiry has been sent. Our team will be in touch.','error'=>'Your enquiry could not be sent. Please try again or contact the team directly.','expired'=>'Your session expired. Please refresh this page and try again.','invalid'=>'Please complete your name, a valid email, a message of at least 10 characters and the privacy acknowledgement.','rate'=>'Please wait a minute before sending another enquiry.'];if(isset($messages[$status])): ?><p class="form-status" role="status"><?php echo esc_html($messages[$status]); ?></p><?php endif; ?><label for="full-name">Name *</label><input id="full-name" name="full_name" autocomplete="name" maxlength="150" required><label for="email">Email *</label><input id="email" type="email" name="email" autocomplete="email" maxlength="200" required><label for="phone">Phone</label><input id="phone" type="tel" name="phone" autocomplete="tel" maxlength="50"><label for="practice-area">Practice area</label><select id="practice-area" name="practice_area"><option value="">Please select</option><?php foreach(rzz_areas() as $slug=>$area): ?><option <?php selected(is_singular('expertise')&&get_post_field('post_name',get_the_ID())===$slug); ?> value="<?php echo esc_attr($area[0]); ?>"><?php echo esc_html($area[0]); ?></option><?php endforeach; ?></select><label for="message">Message *</label><textarea id="message" name="message" rows="3" minlength="10" maxlength="10000" required></textarea><label class="privacy-check"><input type="checkbox" name="privacy" value="1" required><span>I have read the <a href="<?php echo esc_url(rzz_link('privacy-policy')); ?>">Privacy Policy</a> and acknowledge the processing of my enquiry.</span></label><p class="form-note">Please avoid sending sensitive documents before we confirm the appropriate way to share them.</p><button class="button" type="submit">Send enquiry <?php echo rzz_arrow(); ?></button></form>